import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

import javax.sql.DataSource;

import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;

import sailpoint.server.Environment;

    Log log = LogFactory.getLog("sailpoint.rule.Rule_CorrectBadIDX");

    // Set to 'true' to test only.
    // No changes are made
    boolean DEBUG_ONLY = false;

    // The names of the table and corresponding
    // parent. The below String constants need to
    // be changed depending on where the IDX
    // problem exists. The following is a list of
    // possible table/parent combinations where
    // IDX issues have been seen.
    //
    // UNIX MYSQL NOTE: There have been issues with
    // this script in regards to case sensitivity of
    // various database table names. These should
    // be resolved, but if you run into issues with
    // "not found" messages appearing, please
    // reference your MySQL documentation. Example:
    // MySQL 5.1 Reference Manual(9.2.2 Identifier Case Sensitivity)
    //
    // TABLE:  SPT_LINK
    // PARENT: IDENTITY_ID
    //
    // TABLE:  SPT_CERTIFICATION_ITEM
    // PARENT: CERTIFICATION_ENTITY_ID
    //
    // TABLE:  SPT_CERTIFICATION_ENTITY
    // PARENT: CERTIFICATION_ID
    //
    // TABLE:  SPT_REMEDIATION_ITEM
    // PARENT: WORK_ITEM_ID
    //
    //String TABLE = "SPT_APPLICAITON_SCHEMA";
    //String PARENT = "APPLICATION";

    String TABLE = "SPT_SCOPE";
    String PARENT = "PARENT_ID";



    /** Do NOT modify anything below **/
	String CHILDREN_LIST = "children";
	String IDX = "IDX";
	String ID = "ID";
	String NO_ID = "NO_ID";

   //Prepared statements
    Environment e = Environment.getEnvironment();
    DataSource src = e.getSpringDataSource();
    log.debug("DataSource: " + src.toString());
    connection = src.getConnection();
    log.debug("Connection: " + connection);
    String findBadIdxSql = "select id, " + PARENT + ", idx from " + TABLE + " order by " + PARENT + ", idx asc";
    String correctParentSql = "select id, idx from " + TABLE + " where " + PARENT + " = ? order by idx asc";
    String updateSql = "update " + TABLE + " set IDX = ? where ID = ?";


    PreparedStatement findBadIdxSqlStmt = connection.prepareStatement(findBadIdxSql);
    PreparedStatement correctParentSqlStmt = connection.prepareStatement(correctParentSql);
    PreparedStatement updateSqlStmt = connection.prepareStatement(updateSql);



	Map getNextRow(ResultSet rs) throws SQLException {
		log.debug("Entering getNextRow: rs=" + rs);
		Map results = null;
		if (rs.next()) {
			if (results == null) {
				results = new HashMap();
			}
			ResultSetMetaData md = rs.getMetaData();
			int cols = md.getColumnCount();
			log.debug("Columns: " + cols);
			for (int i = 1; i <= cols; i++) {
				String colName = md.getColumnLabel(i);
				String colValue = rs.getString(i);
				log.debug("column: " + colName + " : " + colValue);
				results.put(colName.toUpperCase(), colValue);
			}
		}
		log.debug("Exiting getNextRow (" + results + ")");
		return results;
	}

	boolean examineParent(Map parentObj) {
		log.debug("Entering examineParent(" + parentObj + ")");
		List children = (List) parentObj.get(CHILDREN_LIST);
		Set idxs = new TreeSet();
		int maxIdx = 0;
		for (Object childObj : children) {
			Map child = (Map)childObj;
			String childIdx = (String) child.get(IDX);
			if (childIdx != null && !childIdx.equals("")) {
				int idxInt = Integer.valueOf(childIdx);
				if (idxInt > maxIdx) {
					maxIdx = idxInt;
				}
				idxs.add(childIdx);
			} else {
				//  null or empty child idx.  If hte list is more than one, whoop whoop!
				if (children.size() > 1) {
					log.debug("Exiting examineParent(true) -- null / empty IDX with multiple children");
					return true;
				}
			}

		}
		// validate idxs set
		// - Null values were already found by now, no need to check that
		// - overlaps are detected very easily: the size of the set won't match the size of the children
		// - Gaps are found if the smallest element isn't 0 and the largest element isn't size - 1
		if (children.size() != idxs.size() || maxIdx != idxs.size() - 1) {
			log.debug("Exiting examineParent(true) -- size diff");
			return true;
		} else {
			if (!idxs.contains("0")) { // this may be moo. previous logic seems to capture all possible scenarios
				log.debug("Exiting examineParent(true) -- doesn't contain 0");
				return true;
			}
		}
		log.debug("Exiting examineParent(false)");
		return false;
	}

    Set findBadIdx(String table) throws SQLException {
        log.debug("Entering findBadIdx: table=" + table);
        Set ids = new HashSet();
        //String sql = "select id, " + PARENT + ", idx from " + TABLE + " order by " + PARENT + ", idx asc";
        ResultSet rs = null;
        try {
            rs = findBadIdxSqlStmt.executeQuery();
            boolean done = false;
            String lastParentId = NO_ID;
            Map parentObj = new HashMap();
            List children = new ArrayList();
            parentObj.put(CHILDREN_LIST, children);
            while (!done) {
                Map nextRow = getNextRow(rs);
                if (nextRow != null) {
                    String parentId = (String) nextRow.get(PARENT.toUpperCase());
                    if (parentId != null && !parentId.equals("")) {
                        if (NO_ID.equals(lastParentId)) {
                            lastParentId = parentId;
                        }

                        if (!lastParentId.equals(parentId)) {
                            // got all our children for this parent, process before moving on
                            if (examineParent(parentObj)) {
                                ids.add(parentObj.get(PARENT));
                            }
                            lastParentId = parentId;
                            parentObj = new HashMap();
                            children = new ArrayList();
                            parentObj.put(CHILDREN_LIST, children);
                        }

                        parentObj.put(PARENT, parentId);
                        String childId = (String) nextRow.get(ID);
                        String childIdx = (String) nextRow.get(IDX);
                        Map childMap = new HashMap();
                        childMap.put(ID, childId);
                        childMap.put(IDX, childIdx);
                        children.add(childMap);
                    }
                } else {
                    if (examineParent(parentObj)) {
                        ids.add(parentObj.get(PARENT));
                    }
                    done = true;
                }
            }
        } finally {
        if(rs != null)
            rs.close();
        }

        log.debug("Exiting findBadIdx: ids=" + ids);
        return ids;
    }

    void correctParent(String id) throws SQLException {
        log.debug("Entering correctParent: select id, idx from " + TABLE + " where " + PARENT + " = '" + id + "' order by idx asc");
        ResultSet rs = null;
        try {
            correctParentSqlStmt.setString(1, id);
            rs = correctParentSqlStmt.executeQuery();


            // we're just going to reset the idx.
            List idIdx = new ArrayList();
            boolean done = false;
            int count = 0;
            int rows = 0;
            while (!done) {
                Map nextRow = getNextRow(rs);
                //log.debug("nextRow: " + nextRow);
                if (nextRow == null) {
                    done = true;
                    continue;
                }
                String childId = (String) nextRow.get(ID);
                String currentIdx = (String) nextRow.get(IDX);
                String strCount = String.valueOf(count);
                if (!strCount.equals(currentIdx)) {
                    //String updateSql = "update " + TABLE + " set IDX = " + count + " where ID = '" + childId + "'";
                    updateSqlStmt.setInt(1,count);
                    updateSqlStmt.setString(2,childId);
                    rows =  updateSqlStmt.executeUpdate();
                    if (rows == 0) {
                        log.warn("No Rows modified!");
                    } else if (rows > 1) {
                        log.warn("More than 1 row modified! (" + rows + ")");
                    } else {
                        log.debug("Rows modified: " + rows);
                        count++;
                    }
                } else {
                    count++;
                }
            }
        } finally {
         if(rs != null)
            rs.close();
        }
        log.debug("Exiting correctParent: " + id);
    }

		/** Main **/
        StringBuffer buff = new StringBuffer();
        try {
            try {
                // Find null idx
                Set ids = findBadIdx(TABLE);
                buff.append("\n");
                buff.append("Examining table: " + TABLE + "\n");
                buff.append("Found ids: " + ids + "\n");
                log.warn("Found ids: " + ids);

                if (!DEBUG_ONLY) {
                    Iterator iter = ids.iterator();
                    while (iter.hasNext()) {
                        String id = (String) iter.next();
                        log.warn("Correcting parent: " + id);
                        correctParent(id);
                        buff.append("Corrected parent object: " + id + "\n");
                    }
                } else {
                    log.warn("Skipping corrective action (DEBUG_ONLY = true)");
                }
            } finally {
                findBadIdxSqlStmt.close();
                correctParentSqlStmt.close();
                updateSqlStmt.close();
                connection.close();
            }
        } catch (SQLException e1) {
            log.error("SQL Error",e1);
            e1.printStackTrace();
            throw e1;
        }

        return buff.toString();
